g.community_id = #{actor.communityId}
AND EXISTS (SELECT 1 FROM elder_account_binding eb JOIN user_account owner ON owner.id = eb.account_id JOIN elder_profile e ON e.id = eb.elder_id WHERE AND e.id = g.elder_id AND e.community_id = g.community_id AND eb.account_id = #{actor.id})
AND g.recipient_id = #{actor.id} AND g.scope = 'FAMILY_READ' AND g.recipient_id = #{actor.id} AND g.scope = 'COMMUNITY_ASSIST' AND 1 = 0

