UPDATE health_grant SET revoked = TRUE, revoked_at = #{now}, revoked_by = #{actorId}, version = version + 1
WHERE community_id = #{community} AND elder_id = #{elderId} AND recipient_id = #{recipientId}
  AND scope = #{scope} AND revoked = FALSE
